CREATE DATABASE IF NOT EXISTS snapit CHARACTER SET utf8mb4; USE snapit;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, role ENUM('customer','staff') NOT NULL DEFAULT 'customer', full_name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE packages(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL, soft_copy_limit INT NOT NULL, hard_copy_limit INT NOT NULL, has_hardcopy_addon BOOLEAN NOT NULL DEFAULT 0, has_softcopy_addon BOOLEAN NOT NULL DEFAULT 0, base_price DECIMAL(10,2) NOT NULL, description TEXT);
CREATE TABLE camera_models(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL, preview_style_config JSON, thumbnail_path VARCHAR(255));
CREATE TABLE filters(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL, css_filter_value VARCHAR(255) NOT NULL);
CREATE TABLE layouts(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL, slot_count INT NOT NULL, template_config JSON);
CREATE TABLE frame_designs(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL, overlay_image_path VARCHAR(255), compatible_layout_id INT NULL, FOREIGN KEY(compatible_layout_id) REFERENCES layouts(id));
CREATE TABLE bookings(id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, package_id INT NOT NULL, event_date DATE NOT NULL, start_time TIME NOT NULL, duration_hours INT NOT NULL, status ENUM('pending','confirmed','paid','completed','cancelled') NOT NULL DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, CHECK(duration_hours BETWEEN 6 AND 12), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(package_id) REFERENCES packages(id));
CREATE TABLE booking_packages(id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, package_id INT NOT NULL, soft_copy_limit_snapshot INT NOT NULL, hard_copy_limit_snapshot INT NOT NULL, has_softcopy_addon_snapshot BOOLEAN NOT NULL, price_snapshot DECIMAL(10,2) NOT NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(package_id) REFERENCES packages(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, amount DECIMAL(10,2) NOT NULL, payment_date DATETIME, method ENUM('cash') NOT NULL DEFAULT 'cash', status ENUM('unpaid','paid') NOT NULL DEFAULT 'unpaid', recorded_by_staff_id INT, receipt_number VARCHAR(30), FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(recorded_by_staff_id) REFERENCES users(id));
CREATE TABLE sessions(id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, camera_model_id INT NOT NULL, layout_id INT NOT NULL, started_at DATETIME DEFAULT CURRENT_TIMESTAMP, ended_at DATETIME NULL, end_reason ENUM('manual','idle_timeout') NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(camera_model_id) REFERENCES camera_models(id), FOREIGN KEY(layout_id) REFERENCES layouts(id));
CREATE TABLE photos(id INT AUTO_INCREMENT PRIMARY KEY, session_id INT NOT NULL, filter_id INT, frame_design_id INT, file_path VARCHAR(255) NOT NULL, slot_index INT, is_kept BOOLEAN DEFAULT 1, captured_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES sessions(id), FOREIGN KEY(filter_id) REFERENCES filters(id), FOREIGN KEY(frame_design_id) REFERENCES frame_designs(id));
CREATE TABLE photo_deliveries(id INT AUTO_INCREMENT PRIMARY KEY, session_id INT NOT NULL, delivery_type ENUM('email','download','hardcopy') NOT NULL, recipient_email VARCHAR(160) NULL, delivery_status ENUM('pending','sent','failed') DEFAULT 'pending', requires_softcopy_addon BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE inventory_items(id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(80) NOT NULL, quantity_on_hand INT NOT NULL, reorder_threshold INT NOT NULL, unit VARCHAR(20), consumption_per_print DECIMAL(6,2) DEFAULT 1);
CREATE TABLE print_jobs(id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, photo_id INT NOT NULL, status ENUM('queued','printing','completed') DEFAULT 'queued', queued_at DATETIME DEFAULT CURRENT_TIMESTAMP, printed_at DATETIME NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(photo_id) REFERENCES photos(id));
CREATE TABLE notifications_log(id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, type ENUM('booking_confirmation','reminder','softcopy_sent_admin_notice') NOT NULL, sent_at DATETIME DEFAULT CURRENT_TIMESTAMP, status ENUM('sent','failed') NOT NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id));
